-- +goose Up
-- +goose StatementBegin

-- Constraints and indexes that replace the NATS KV lookup keys. Every unique index below reproduces
-- the normalization of the KV key it replaces (see the BuildIndexKey methods in
-- internal/domain/model), so a record the KV store accepts is accepted here and a duplicate the KV
-- store rejects is rejected here, with the residual differences noted below.
--
-- The KV keys also lowercase and trim committee_uid. Committee UIDs are lowercase UUIDs generated by
-- the service, so the unique indexes use committee_uid as stored; the planned `verify` command
-- (lfx-self-serve-ops#1198) is meant to report any backfilled row where that does not hold.

-- committee_normalize_key reproduces the Go normalization the KV keys apply to emails and usernames,
-- strings.TrimSpace(strings.ToLower(x)). PostgreSQL's btrim(x) only strips ASCII spaces, whereas Go
-- strips every Unicode white space character (tab, newline, no-break space, ...), so the character set
-- below lists the same characters as unicode.IsSpace.
--
-- lower() follows the database locale, and the Turkic locales (tr, az) lowercase I to a dotless i,
-- which Go does not. I and the dotted capital I (U+0130) are therefore mapped to i first, which is
-- what Go does for both, so the result does not depend on the locale. Every other character uses the
-- database's simple per-character case mapping, which matches Go on a database with the libc locale
-- provider and a UTF-8 locale (the default) apart from rare characters whose case differs between
-- Unicode versions. A C/POSIX database folds ASCII only, and an ICU-provider database applies
-- contextual casing (final sigma: ICU lowercases to a final sigma, Go does not), so create the
-- database with the libc provider. docs/postgres-schema.md has the details.
CREATE FUNCTION committee_normalize_key(value TEXT) RETURNS TEXT
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
        SELECT lower(btrim(replace(replace(value, 'I', 'i'), U&'\0130', 'i'),
            U&' \0009\000A\000B\000C\000D\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000'))
    $$;

-- ---------------------------------------------------------------------------------------
-- Uniqueness (KV: lookup/... keys)

-- lookup/committees/<sha256(project_uid|name)>: one name per project, case-sensitive.
CREATE UNIQUE INDEX committees_project_name_key ON committees (project_uid, name);

-- lookup/committee-sso-groups/<name>: an empty name means "none", so the index is partial.
CREATE UNIQUE INDEX committees_sso_group_name_key ON committees (sso_group_name) WHERE sso_group_name <> '';

-- lookup/committee-members/<sha256(committee_uid|email)>, email trimmed and lowercased.
CREATE UNIQUE INDEX committee_members_committee_email_key
    ON committee_members (committee_uid, committee_normalize_key(email));

-- lookup/committee-invites/<sha256(committee_uid|invitee_email)>. One invite per (committee, email):
-- a declined or expired invite is reinstated rather than recreated (#1206), so this stays plain.
CREATE UNIQUE INDEX committee_invites_committee_email_key
    ON committee_invites (committee_uid, committee_normalize_key(invitee_email));

-- lookup/committee-applications/<sha256(committee_uid|applicant_email)>.
CREATE UNIQUE INDEX committee_applications_committee_email_key
    ON committee_applications (committee_uid, committee_normalize_key(applicant_email));

-- lookup/committee-folders/<sha256(committee_uid|name)>, case-sensitive.
CREATE UNIQUE INDEX committee_link_folders_committee_name_key ON committee_link_folders (committee_uid, name);

-- lookup/committee-documents/<sha256(committee_uid|name)>, case-sensitive.
CREATE UNIQUE INDEX committee_documents_committee_name_key ON committee_documents (committee_uid, name);

-- group-weekly-brief-uid-index: <committee_uid>.<yyyymmdd of the window start, in UTC>. The throttle
-- bucket uses the same key, and its primary key already rejects an exact repeat of the timestamp.
CREATE UNIQUE INDEX group_weekly_briefs_committee_window_key
    ON group_weekly_briefs (committee_uid, ((window_start AT TIME ZONE 'UTC')::date));
CREATE UNIQUE INDEX group_weekly_brief_throttle_committee_window_key
    ON group_weekly_brief_throttle (committee_uid, ((window_start AT TIME ZONE 'UTC')::date));

-- ---------------------------------------------------------------------------------------
-- Lookups (KV: the four lookup/committee-members-by-* secondary indexes, and bucket scans)

-- by-committee: "all members of a committee" is served by the unique index above, which leads with
-- committee_uid (likewise for invites and applications), so it needs no index of its own.
-- by-organization: the KV index keys on the 18-character SFID, which is what organization_id holds.
CREATE INDEX committee_members_organization_id_idx ON committee_members (organization_id) WHERE organization_id <> '';
-- by-email and by-username: the KV indexes hash the trimmed, lowercased value across all committees.
CREATE INDEX committee_members_email_idx ON committee_members (committee_normalize_key(email));
CREATE INDEX committee_members_username_idx ON committee_members (committee_normalize_key(username)) WHERE username <> '';

CREATE INDEX committees_project_uid_idx ON committees (project_uid);
CREATE INDEX committees_parent_uid_idx ON committees (parent_uid) WHERE parent_uid IS NOT NULL;

CREATE INDEX committee_links_committee_uid_idx ON committee_links (committee_uid);
CREATE INDEX committee_links_folder_uid_idx ON committee_links (folder_uid) WHERE folder_uid IS NOT NULL;
CREATE INDEX committee_documents_folder_uid_idx ON committee_documents (folder_uid) WHERE folder_uid IS NOT NULL;

-- Incremental loads (the warehouse pipeline and the planned migrate/verify commands) read by updated_at.
CREATE INDEX committees_updated_at_idx ON committees (updated_at);
CREATE INDEX committee_members_updated_at_idx ON committee_members (updated_at);

-- +goose StatementEnd

-- +goose Down
-- +goose StatementBegin
DROP INDEX IF EXISTS committee_members_updated_at_idx;
DROP INDEX IF EXISTS committees_updated_at_idx;
DROP INDEX IF EXISTS committee_documents_folder_uid_idx;
DROP INDEX IF EXISTS committee_links_folder_uid_idx;
DROP INDEX IF EXISTS committee_links_committee_uid_idx;
DROP INDEX IF EXISTS committees_parent_uid_idx;
DROP INDEX IF EXISTS committees_project_uid_idx;
DROP INDEX IF EXISTS committee_members_username_idx;
DROP INDEX IF EXISTS committee_members_email_idx;
DROP INDEX IF EXISTS committee_members_organization_id_idx;
DROP INDEX IF EXISTS group_weekly_brief_throttle_committee_window_key;
DROP INDEX IF EXISTS group_weekly_briefs_committee_window_key;
DROP INDEX IF EXISTS committee_documents_committee_name_key;
DROP INDEX IF EXISTS committee_link_folders_committee_name_key;
DROP INDEX IF EXISTS committee_applications_committee_email_key;
DROP INDEX IF EXISTS committee_invites_committee_email_key;
DROP INDEX IF EXISTS committee_members_committee_email_key;
DROP INDEX IF EXISTS committees_sso_group_name_key;
DROP INDEX IF EXISTS committees_project_name_key;
DROP FUNCTION IF EXISTS committee_normalize_key(TEXT);
-- +goose StatementEnd
